package gen

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"maps"
	"slices"
	"strings"

	"golang.org/x/tools/go/packages"
)

// file accumulates the generated file of one package.
type file struct {
	pkg     *packages.Package
	decls   map[token.Pos]varDecl
	aliases map[string]string // import path -> alias
	used    map[string]string // alias -> import path
	body    bytes.Buffer
	opts    options
	tree    *strings.Builder // set by Show: print dependency trees instead of code
	types   typeIndex
}

func newFile(pkg *packages.Package, decls map[token.Pos]varDecl) *file {
	return &file{pkg: pkg, decls: decls, aliases: map[string]string{}, used: map[string]string{}}
}

func (f *file) bytes() []byte {
	var b bytes.Buffer
	fmt.Fprintf(&b, "// Code generated by whyor. DO NOT EDIT.\n\n//go:build !whyor\n\npackage %s\n\n", f.pkg.Name)
	if len(f.aliases) > 0 {
		b.WriteString("import (\n")
		for _, p := range slices.Sorted(maps.Keys(f.aliases)) {
			fmt.Fprintf(&b, "\t%s %q\n", f.aliases[p], p)
		}
		b.WriteString(")\n\n")
	}
	b.Write(f.body.Bytes())
	return b.Bytes()
}

// qual is a types.Qualifier that allocates import aliases on demand.
func (f *file) qual(p *types.Package) string {
	if p == f.pkg.Types {
		return ""
	}
	if a, ok := f.aliases[p.Path()]; ok {
		return a
	}
	a := p.Name()
	for i := 2; f.used[a] != "" || token.IsKeyword(a) || types.Universe.Lookup(a) != nil; i++ {
		a = fmt.Sprintf("%s%d", p.Name(), i)
	}
	f.aliases[p.Path()], f.used[a] = a, p.Path()
	return a
}

// reserve forces an import alias, as spelled in a Value expression.
func (f *file) reserve(alias, path string) error {
	if p := f.used[alias]; p != "" && p != path {
		return fmt.Errorf("import alias %q used for both %s and %s", alias, p, path)
	}
	if a := f.aliases[path]; a != "" && a != alias {
		return fmt.Errorf("package %s needed as both %q and %q", path, a, alias)
	}
	f.aliases[path], f.used[alias] = alias, path
	return nil
}

func (f *file) typ(t types.Type) string { return types.TypeString(t, f.qual) }

func (f *file) zero(t types.Type) string {
	switch u := t.Underlying().(type) {
	case *types.Pointer, *types.Interface, *types.Slice, *types.Map, *types.Chan, *types.Signature:
		return "nil"
	case *types.Basic:
		switch {
		case u.Info()&types.IsString != 0:
			return `""`
		case u.Info()&types.IsBoolean != 0:
			return "false"
		case u.Info()&types.IsNumeric != 0:
			return "0"
		}
	}
	return "*new(" + f.typ(t) + ")"
}

func (f *file) injector(fd *ast.FuncDecl, call *ast.CallExpr) error {
	err := f.inject(fd, call)
	if err == nil {
		return nil
	}
	return fmt.Errorf("%s: %s: %w", f.pkg.Fset.Position(call.Pos()), fd.Name.Name, err)
}

func (f *file) inject(fd *ast.FuncDecl, call *ast.CallExpr) error {
	obj, _ := f.pkg.TypesInfo.Defs[fd.Name].(*types.Func)
	sig := obj.Type().(*types.Signature)
	if sig.Recv() != nil || sig.TypeParams().Len() > 0 || sig.Variadic() {
		return fmt.Errorf("injector must be a plain, non-generic, non-variadic function")
	}
	res, err := parseResults(sig)
	if err != nil {
		return err
	}

	c := &collector{f: f, bindings: map[typeID]*binding{}, visiting: map[token.Pos]bool{}, closers: map[typeID]bool{}}
	for _, a := range call.Args {
		if err := c.collect(a, f.pkg); err != nil {
			return err
		}
	}

	r := &resolver{f: f, res: res, bindings: c.bindings, autos: c.autos, closers: c.closers,
		done: map[typeID]string{}, fns: map[*types.Func]string{}}
	var params []string
	for i := range sig.Params().Len() {
		p := sig.Params().At(i)
		name := p.Name()
		if name == "" || name == "_" {
			name = fmt.Sprintf("arg%d", i)
		}
		if _, dup := r.done[f.types.key(p.Type())]; dup {
			return fmt.Errorf("multiple parameters of type %s", f.typ(p.Type()))
		}
		r.done[f.types.key(p.Type())] = name
		params = append(params, name+" "+f.typ(p.Type()))
	}
	given := maps.Clone(r.done)
	out, err := r.resolve(res.out)
	if err != nil {
		return err
	}
	if f.opts.use != nil {
		f.record(c, r)
	}
	if f.tree != nil {
		r.writeGraph(f.tree, fd.Name.Name, res.out, given, f.opts.format)
		return nil
	}

	rets := []string{f.typ(res.out)}
	ret := out
	if res.cleanup {
		rets = append(rets, "func()")
		ret += ", " + r.cleanupFunc()
	}
	if res.err {
		rets = append(rets, "error")
		ret += ", nil"
	}
	retSig := strings.Join(rets, ", ")
	if len(rets) > 1 {
		retSig = "(" + retSig + ")"
	}
	fmt.Fprintf(&f.body, "func %s(%s) %s {\n%s\treturn %s\n}\n\n",
		fd.Name.Name, strings.Join(params, ", "), retSig, r.lines.String(), ret)
	return nil
}

// record notes the providers an injector declares and the ones it calls.
func (f *file) record(c *collector, r *resolver) {
	var declare func(b *binding)
	declare = func(b *binding) {
		if b.fn != nil {
			f.opts.use.declared[b.fn] = f.pkg.Fset.Position(b.fn.Pos())
		}
		for _, e := range b.elems {
			declare(e)
		}
	}
	for _, b := range c.bindings {
		declare(b)
	}
	for fn := range r.fns {
		f.opts.use.used[fn] = true
	}
}
